def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    new_board = [list(row) for row in board]
    char_to_change = new_board[row][col]

    if char_to_change == 'Y':
        new_board[row][col] = 'B'
    elif char_to_change == 'W':
        new_board[row][col] = 'b'
    elif char_to_change == 'c':
        new_board[row][col] = 'b'

    # Change adjacent cells downwards
    for i in range(row+1, 64):
        if new_board[i][col] == 'B':
            new_board[i][col] = 'b'
        elif new_board[i][col] == 'c':
            new_board[i][col] = 'b'

    return [''.join(row) for row in new_board]
